package com.company.tpm.ui;import com.company.tpm.employee.*;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.orderedlayout.VerticalLayout;import com.vaadin.flow.component.textfield.TextField;import com.vaadin.flow.router.*;import jakarta.annotation.security.RolesAllowed;import org.springframework.data.domain.PageRequest;
@Route(value="employees",layout=MainLayout.class)@PageTitle("Employees | TPM")@RolesAllowed({"SUPER_ADMIN","ADMIN","SUPERVISOR"})public class EmployeesView extends VerticalLayout{public EmployeesView(EmployeeService service){var q=new TextField("Search");var g=new Grid<EmployeeDtos.EmployeeResponse>();g.addColumn(EmployeeDtos.EmployeeResponse::staffId).setHeader("Staff ID");g.addColumn(EmployeeDtos.EmployeeResponse::fullName).setHeader("Name");g.addColumn(EmployeeDtos.EmployeeResponse::department).setHeader("Department");g.addColumn(EmployeeDtos.EmployeeResponse::status).setHeader("Status");Runnable load=()->g.setItems(service.search(q.getValue(),PageRequest.of(0,50)).getContent());q.addValueChangeListener(e->load.run());add(q,g);load.run();}}
